import json,re
from pathlib import Path
p=Path(__file__).parent;prior=p.parent/'div-zero-ed3602b';root=Path('/home/hanbo/repo/delta-arrow-reader/experiments/spark-sql')
read=lambda f:json.loads(f.read_text())
checks=read(p/'checks.json');prefix='spark_decimal_null_propagation\ncaused by\n'
changed=[];repaired=[];same_success=0;captures={}
for corpus,result in checks.items():
 before=p/'before-new.json' if corpus=='new' else prior/('after-new.json' if corpus=='div-zero' else f'after-{corpus}.json')
 left={r['id']:r['actual'] for r in read(before)['results']};right={r['id']:r['actual'] for r in read(p/f'after-{corpus}.json')['results']}
 captures[corpus]=(left,right)
 for id,a in left.items():
  b=right[id]
  if a['status']==b['status']=='ok':
   assert a==b,(corpus,id);same_success+=1
  if a.get('error')!=b.get('error'):
   if id in result['repaired']:
    assert a['status']=='ok' and b['status']=='execution_error' and 'Divide by zero' in b['error'],(corpus,id,a,b)
    repaired.append({'corpus':corpus,'id':id,'candidate_error':b['error']});continue
   assert a['status']==b['status']=='execution_error',(corpus,id,a,b)
   old,new=a['error'],b['error']
   if old==new.removeprefix(prefix):kind='same cause with analyzer prefix'
   else:
    pattern=r'Execution error: Cannot cast Some\(.+\) to (DECIMAL\([0-9]+,[0-9]+\))'
    x,y=re.fullmatch(pattern,old),re.fullmatch(pattern,new)
    assert x and y and x[1]==y[1],(corpus,id,old,new)
    kind='same cast class and target type, different first invalid input'
   changed.append({'corpus':corpus,'id':id,'kind':kind,'before':old,'after':new})
old_checks=read(p.parent/'integer-widening-sparse-owned-542a847/extra-checks.json')
focused=[]
for key,default in [('preserved_prior_checks',None),('preserved_same_stage_error_cause_differences',None),('wrapped_sort_type_errors','integral-types'),('preserved_non_float_control_errors','integral-types'),('new_error_causes','integral-widen')]:
 for e in old_checks[key]:
  corpus=e.get('corpus',default);a,b=(rows[e['id']] for rows in captures[corpus]);assert a['status']==b['status']
  normalized=b.get('error','').removeprefix(prefix)
  assert a.get('error','').removeprefix(prefix)==normalized,(corpus,e['id'],a,b)
  if 'rows' in a:assert a['rows']==b['rows'] and a['types']==b['types']
  focused.append({'corpus':corpus,'id':e['id'],'source_group':key,'same_error_cause':True})
causes=[];additional_gaps=[]
for corpus,ref in [('new',p/'spark.json'),('div-zero',prior/'spark.json')]:
 spark={r['id']:r['actual'] for r in read(ref)['results']};after=captures[corpus][1]
 for id,a in spark.items():
  b=after[id]
  if a.get('condition')=='DIVIDE_BY_ZERO' and b['status']=='execution_error':
   if 'Divide by zero' not in b['error']:
    assert corpus=='new' and id in {f'{t}_empty_subquery_true' for t in ['tinyint','smallint','int','bigint']}
    assert b['error']==captures[corpus][0][id]['error'] and 'declared as non-nullable but contains null values' in b['error']
    additional_gaps.append({'corpus':corpus,'id':id,'spark_condition':a['condition'],'candidate_error':b['error'],'unchanged_from_before':True})
    continue
   causes.append({'corpus':corpus,'id':id,'spark_condition':a['condition'],'candidate_error':b['error']})
result={'preserved_focused_checks':focused,'same_successful_observations_including_plans':same_success,'repaired_zero_errors':repaired,'changed_same_stage_errors':changed,'verified_zero_error_causes':causes,'known_same_stage_cause_gaps':old_checks['preserved_same_stage_error_cause_differences'],'wrapped_sort_type_errors':old_checks['wrapped_sort_type_errors'],'additional_same_stage_cause_gaps':additional_gaps}
(p/'focused.json').write_text(json.dumps(result,indent=2)+'\n')
print(len(focused),'prior focused checks preserved;',len(repaired),'new zero errors;',len(changed),'same-stage diagnostics changed;',same_success,'successful observations and plans unchanged')

